import{_ as a,o,c as t,a2 as s}from"./chunks/framework.Crpw6aS5.js";const r="/apps/revdash-icon.png",i="/assets/01-og.DwB-JYz-.png",l="/assets/02-shot.DvWNNViJ.png",n="/assets/03-shot.MoUduJs7.png",d="/assets/04-shot.Dtads4w7.png",p="/assets/05-shot.BRlPxvdd.png",h="/assets/06-shot.DrfU8bET.png",c="/assets/07-shot.D6vtqfIc.png",g="/assets/08-shot.WuZigzRb.png",u="/assets/09-shot.DvTMRbK5.png",m="/assets/10-shot.CfSB39_9.png",k=JSON.parse('{"title":"RevDash (Google Play)","description":"Google Play listing notes for RevDash — live OBD-II dashboard for Android.","frontmatter":{"title":"RevDash (Google Play)","description":"Google Play listing notes for RevDash — live OBD-II dashboard for Android."},"headers":[],"relativePath":"software-engineering/android-app-development/play-google-com-revdash.md","filePath":"software-engineering/android-app-development/play-google-com-revdash.md"}'),v={name:"software-engineering/android-app-development/play-google-com-revdash.md"};function f(y,e,D,b,_,P){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="revdash-google-play" tabindex="-1">RevDash (Google Play) <a class="header-anchor" href="#revdash-google-play" aria-label="Permalink to &quot;RevDash (Google Play)&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://play.google.com/store/apps/details?id=app.revdash.obd" target="_blank" rel="noreferrer">Google Play — RevDash</a></li><li>Site: <a href="https://revdash.me/" target="_blank" rel="noreferrer">revdash.me</a> (see also <a href="./../../obd2/related-projects/revdash-me.html">RevDash marketing/docs ingest</a>)</li><li>Imported: 2026-09-17</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><img src="'+r+'" alt="RevDash app icon"></p><p><strong>Developer:</strong> APPSOLUTE SOLUTIONS (PTY) LTD · <strong>Package:</strong> <code>app.revdash.obd</code> · <strong>Category:</strong> Auto &amp; Vehicles · <strong>Rating:</strong> Everyone · <strong>Updated:</strong> Sep 16, 2026</p><p><strong>Tagline:</strong> Live OBD2 dashboard &amp; code reader. Custom gauges, trip logs, and zero ads.</p><p><img src="'+i+'" alt="RevDash Play Store feature graphic — live gauges for RPM, speed, coolant, battery"></p><p>RevDash is a live OBD-II dashboard for Android. Plug in a Bluetooth ELM327 adapter, connect once, and read engine data on a dark gauge grid that keeps polling in the background.</p><h3 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h3><ul><li>An ELM327-compatible Bluetooth Classic or BLE adapter</li><li>A vehicle that speaks generic OBD-II (powertrain)</li><li>Android 8.0 or later</li></ul><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Live gauges:</strong> RPM, speed, coolant, throttle, load, battery voltage, and other Mode 01 PIDs your ECU reports</li><li><strong>VAG extras:</strong> oil temp, charge pressure (actual/spec), torque, lambda, timing, rail pressure, wastegate when your VW/Audi/SEAT/Skoda answers Mode 22</li><li><strong>Estimated gear:</strong> derived from RPM and speed (same idea as TrackAddict); works on manuals too</li><li><strong>Custom dash:</strong> add, remove, drag, and resize tiles; each vehicle profile keeps its own layout</li><li><strong>Connection that explains itself:</strong> one-tap reconnect, adapter bound to the vehicle profile, protocol hint, and a diagnostics screen that separates “Couldn’t reach adapter” from “Adapter OK, no ECU”</li><li><strong>Check-engine workflow:</strong> stored, pending, and permanent codes, freeze frame, generic SAE titles, clear only after you confirm</li><li><strong>Charts:</strong> live traces with 15s to 5m windows</li><li><strong>Trip CSV:</strong> GPS + OBD rows you save to a file you can open</li><li><strong>Backup:</strong> export and import vehicles and layouts as a zip</li><li><strong>Themes:</strong> Night, Day, OLED, Midnight; metric or imperial; keep-screen-on</li></ul><h3 id="what-revdash-does-not-do" tabindex="-1">What RevDash does not do <a class="header-anchor" href="#what-revdash-does-not-do" aria-label="Permalink to &quot;What RevDash does not do&quot;">​</a></h3><ul><li>Does not read ABS, airbags, or body modules on generic OBD-II</li><li>Does not write to the ECU or run actuator tests</li><li>Is not a shop scan tool and not affiliated with any vehicle maker</li></ul><h3 id="data-safety-play-declaration" tabindex="-1">Data safety (Play declaration) <a class="header-anchor" href="#data-safety-play-declaration" aria-label="Permalink to &quot;Data safety (Play declaration)&quot;">​</a></h3><ul><li>No data shared with third parties</li><li>No data collected</li></ul><h3 id="app-support" tabindex="-1">App support <a class="header-anchor" href="#app-support" aria-label="Permalink to &quot;App support&quot;">​</a></h3><ul><li>Support email: <a href="mailto:dnorgarb@gmail.com" target="_blank" rel="noreferrer">dnorgarb@gmail.com</a></li><li>Developer contact: APPSOLUTE SOLUTIONS (PTY) LTD · <a href="mailto:devin@appsolutedev.com" target="_blank" rel="noreferrer">devin@appsolutedev.com</a> · Cape Town, South Africa</li></ul><h3 id="figures" tabindex="-1">Figures <a class="header-anchor" href="#figures" aria-label="Permalink to &quot;Figures&quot;">​</a></h3><p>Store screenshots from the listing (portrait and landscape variants):</p><p><img src="'+l+'" alt="RevDash — editable dashboard tiles with RPM dial, speed bar, coolant, throttle"></p><p><img src="'+n+'" alt="RevDash Settings — vehicle profiles, Night/Day/OLED/Midnight themes, metric units"></p><p><img src="'+d+'" alt="RevDash PIDs (landscape) — enable sensors the car answered; Mode 01 and computed"></p><p><img src="'+p+'" alt="RevDash PIDs (portrait) — search, show all known, enable/disable toggles"></p><p><img src="'+h+'" alt="RevDash Charts — live RPM, speed, coolant, throttle traces with 15s–5m windows"></p><p><img src="'+c+'" alt="RevDash live dash — Ready on ISO 15765-4 CAN with six PIDs"></p><p><img src="'+g+'" alt="RevDash Codes — stored DTCs, readiness monitors, clear with confirm"></p><p><img src="'+u+'" alt="RevDash Codes (landscape) — check-engine status and stored P0 codes"></p><p><img src="'+m+'" alt="RevDash Dash (landscape) — large Engine RPM gauge over CAN"></p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li><strong>RevDash</strong> (<code>app.revdash.obd</code>) is a free, ad-free Android OBD-II dash for ELM327 Classic/BLE — live gauges, custom layouts, charts, DTC workflow, trip CSV.</li><li>Honest scope: generic powertrain Mode 01 (+ VAG Mode 22 extras); no ABS/SRS/body modules; no ECU writes except confirmed code clear.</li><li>Play Data safety: no collection, no third-party sharing.</li><li>Store link: <a href="https://play.google.com/store/apps/details?id=app.revdash.obd" target="_blank" rel="noreferrer">RevDash on Google Play</a></li></ul>',32)])])}const R=a(v,[["render",f]]);export{k as __pageData,R as default};
